let stockArr = [];
let stockStr = "";
for (const item of $input.all()) {
  stockArr.push(item.json["stock_key"]);
  stockStr = stockArr.map(x => "'" + x + "'").join(",");
}

return [{ 
  stock_keys: stockArr,
  stock_keys_str: stockStr 
}];

smaArr = [];
for (const item of $input.first().json.data) {
  if (item.window_padding == 1) continue;
  calculatedItem = {
    trade_date: item.trade_date,
    symbol: item.stock_key,
    sma_20: item.sum_close_20 / 20,
    sma_50: item.sum_close_50 / 50,
    sma_100: item.sum_close_100 / 100
  }
  smaArr.push(calculatedItem)
}

return smaArr;

const records = [];

for (const item of $input.all()) {
  records.push(item.json);
}

const jsonEachRowString = records.map(row => JSON.stringify(row)).join('\n');

return {
  json: {
    formatted_data: jsonEachRowString
  }
};

data = $input.first().json.data;

// Distribute raw data rows into groups by stock_key
grouped = {};
for (const item of data) {
  if (!grouped[item.stock_key]) grouped[item.stock_key] = [];
  grouped[item.stock_key].push(item);
}

periods = [7, 14, 21];
rsiArr = [];

for (const symbol in grouped) {
  rows = grouped[symbol].sort((a, b) => new Date(a.trade_date) - new Date(b.trade_date));

  state = {};
  for (const p of periods) {
    state[p] = { ag: null, al: null, sumGain: 0, sumLoss: 0 };
  }

  rows.forEach((item, i) => {
    rowsSeen = i + 1;
    calculatedItem = {
      trade_date: item.trade_date,
      symbol: symbol
    };

    for (const p of periods) {
      state[p].sumGain += item.gain;
      state[p].sumLoss += item.loss;

      if (rowsSeen < p) {
        calculatedItem['rsi_' + p] = null;
        continue;
      }

      if (rowsSeen === p) {
        // Seed: initial average gain/loss over the first n periods
        state[p].ag = state[p].sumGain / p;
        state[p].al = state[p].sumLoss / p;
      } else {
        // Wilder's smoothing recursion
        state[p].ag = (state[p].ag * (p - 1) + item.gain) / p;
        state[p].al = (state[p].al * (p - 1) + item.loss) / p;
      }

      ag = state[p].ag;
      al = state[p].al;
      calculatedItem['rsi_' + p] = al === 0 ? (ag === 0 ? 50 : 100) : 100 - (100 / (1 + (ag / al)));
    }
    if (item.window_padding != 1) rsiArr.push(calculatedItem);
  });
}

return rsiArr;

const daysToSubtract = 150;

for (const item of $input.all()) {
  const originalDate = new Date(item.json.start_date);
  originalDate.setDate(originalDate.getDate() - daysToSubtract);
  item.json.data_start_date = originalDate.toISOString().split('T')[0];
}

return $input.all();

function getPercentile(arr, percentile) {
  if (arr.length === 0) return 0;
  if (arr.length === 1) return arr[0];

  const sorted = [...arr].sort((a, b) => a - b);
  const index = (sorted.length - 1) * percentile;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  const weight = index - lower;

  if (upper >= sorted.length) return sorted[sorted.length - 1];
  return sorted[lower] * (1 - weight) + sorted[upper] * weight;
}

const windowSize = 20;

// Extract rows array from ClickHouse JSON wrapper ($input.first().json.data)
const inputData = $input.first()?.json?.data || [];

// Group items by stock_key
const groupedData = {};
for (const item of inputData) {
  const stock = item.stock_key;
  if (!groupedData[stock]) {
    groupedData[stock] = [];
  }
  groupedData[stock].push(item);
}

const outputItems = [];

// Process each stock group
for (const stock in groupedData) {
  const stockItems = groupedData[stock].sort(
    (a, b) => new Date(a.trade_date) - new Date(b.trade_date)
  );

  for (let i = 0; i < stockItems.length; i++) {
    const currentItem = stockItems[i];

    if (Number(currentItem.window_padding) === 0) {
      const startIndex = Math.max(0, i - windowSize + 1);
      const windowVolumes = stockItems
        .slice(startIndex, i + 1)
        .map((d) => parseFloat(d.volume) || 0);

      const p25 = getPercentile(windowVolumes, 0.25);
      const p75 = getPercentile(windowVolumes, 0.75);
      const iqr = p75 - p25;

      outputItems.push({
        json: {
          trade_date: currentItem.trade_date,
          symbol: currentItem.stock_key,
          volume_iqr_p25: Number(p25.toFixed(4)),
          volume_iqr_p75: Number(p75.toFixed(4)),
          volume_rolling_iqr: Number(iqr.toFixed(4))
        }
      });
    }
  }
}

return outputItems;
